import {nav,foods,bases,topics} from './data.js';
import {parseRoute,filterFoods,activeSectionAtLine} from './logic.js';
import {icon} from './icons.js';
import * as views from './views.js';
const main=document.querySelector('#main'), sidebar=document.querySelector('#sidebar'), navigation=document.querySelector('#navigation'), marker=document.querySelector('#nav-marker'), toggle=document.querySelector('#sidebar-toggle'), menu=document.querySelector('#mobile-menu'), close=document.querySelector('#drawer-close'), backdrop=document.querySelector('#drawer-backdrop');
const mobile=matchMedia('(max-width:959px)'), reduced=matchMedia('(prefers-reduced-motion:reduce)');
let route=parseRoute(location.hash), renderedPage='', drawerOpen=false, collapsed=false, observer=null, lastFoodList='#foods', scrollPending=false;
try{collapsed=localStorage.getItem('junyang-sidebar')==='collapsed';}catch{}
navigation.querySelectorAll('.nav-link').forEach(x=>x.remove());
navigation.insertAdjacentHTML('beforeend',nav.map(x=>`<a class="nav-link" data-nav="${x.id}" data-label="${x.label}" href="${x.route}">${icon(x.icon)}<span class="nav-label">${x.label}</span></a>`).join(''));
document.querySelector('.brand-mark').innerHTML=icon('sprout');
menu.innerHTML=`${icon('menu')}<span>菌养食材</span>`;close.innerHTML=icon('close');
function setCollapsed(value){collapsed=value;document.body.classList.toggle('sidebar-collapsed',value);toggle.innerHTML=icon(value?'expand':'collapse')+`<span class="toggle-label">${value?'展开侧栏':'收起侧栏'}</span>`;toggle.setAttribute('aria-label',value?'展开侧栏':'收起侧栏');toggle.setAttribute('aria-expanded',String(!value));try{localStorage.setItem('junyang-sidebar',value?'collapsed':'expanded');}catch{}requestAnimationFrame(syncActive);}
function setDrawer(value,returnFocus=true){drawerOpen=value;document.body.classList.toggle('drawer-open',value);backdrop.hidden=!value;menu.setAttribute('aria-expanded',String(value));main.inert=mobile.matches&&value;sidebar.inert=mobile.matches&&!value;if(value)close.focus();else if(returnFocus&&mobile.matches)menu.focus();}
function syncMobile(){setDrawer(false,false);sidebar.inert=mobile.matches;main.inert=false;requestAnimationFrame(syncActive);}
toggle.addEventListener('click',()=>setCollapsed(!collapsed));menu.addEventListener('click',()=>setDrawer(!drawerOpen));close.addEventListener('click',()=>setDrawer(false));backdrop.addEventListener('click',()=>setDrawer(false));mobile.addEventListener('change',syncMobile);
document.addEventListener('keydown',e=>{if(drawerOpen&&mobile.matches){if(e.key==='Escape'){e.preventDefault();setDrawer(false);return;}if(e.key==='Tab'){const nodes=[...sidebar.querySelectorAll('a,button')].filter(x=>x.getClientRects().length&&!x.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}});
const parentSection=page=>({foods:'food',food:'food',inputs:'inputs',input:'inputs',bases:'base',base:'base',articles:'knowledge',article:'knowledge',events:'events',event:'events'})[page]||'home';
function setActive(id){for(const a of navigation.querySelectorAll('.nav-link')){const current=a.dataset.nav===id;if(current)a.setAttribute('aria-current',route.page==='home'?'location':'page');else a.removeAttribute('aria-current');a.href=route.page==='home'?'#section/'+a.dataset.nav:nav.find(x=>x.id===a.dataset.nav).route;if(current){marker.style.transform=`translateY(${a.offsetTop}px)`;marker.style.height=`${a.offsetHeight}px`;}}}
function syncActive(){if(route.page!=='home'){setActive(parentSection(route.page));return;}const sections=[...main.querySelectorAll('[data-section]')].map(x=>({id:x.dataset.section,...(()=>{const r=x.getBoundingClientRect();return {top:r.top,bottom:r.bottom};})()}));const bottom=scrollY+innerHeight>=document.documentElement.scrollHeight-3;setActive(activeSectionAtLine(sections,innerHeight,bottom));}
window.addEventListener('scroll',()=>{if(scrollPending)return;scrollPending=true;requestAnimationFrame(()=>{syncActive();scrollPending=false;});},{passive:true});window.addEventListener('resize',()=>requestAnimationFrame(syncActive));
function reveal(){observer?.disconnect();document.documentElement.classList.remove('motion-ready');if(reduced.matches||!('IntersectionObserver' in window))return;const items=main.querySelectorAll('.section-head,.category-item,.inputs-grid article,.base-feature,.knowledge-layout,.event-intro,.intro-photo');items.forEach(x=>x.classList.add('reveal'));observer=new IntersectionObserver(entries=>{entries.forEach(x=>{if(x.isIntersecting){x.target.classList.add('visible');observer.unobserve(x.target);}});},{threshold:.08});document.documentElement.classList.add('motion-ready');items.forEach(x=>observer.observe(x));}
reduced.addEventListener('change',()=>{observer?.disconnect();document.documentElement.classList.remove('motion-ready');});
function jump(id){const el=document.getElementById(id);if(el)el.scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'start'});}
sidebar.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;if(mobile.matches)setDrawer(false);if(route.page==='home'&&a.getAttribute('href')===location.hash){e.preventDefault();if(a.dataset.nav)jump('section-'+a.dataset.nav);else window.scrollTo({top:0,behavior:reduced.matches?'instant':'smooth'});}});
document.addEventListener('click',e=>{if(e.target.closest('.skip-link')){e.preventDefault();main.focus({preventScroll:false});return;}const explore=e.target.closest('[data-explore]');if(explore){e.preventDefault();jump('intro');return;}const top=e.target.closest('[data-top]');if(top){window.scrollTo({top:0,behavior:reduced.matches?'instant':'smooth'});return;}const jumpLink=e.target.closest('[data-jump]');if(jumpLink){e.preventDefault();jump(jumpLink.dataset.jump);const target=document.getElementById(jumpLink.dataset.jump);target.tabIndex=-1;target.focus({preventScroll:true});}});
function setQuery(query){const values=Object.fromEntries(Object.entries(query).filter(([,v])=>v&&v!=='all'));const tail=new URLSearchParams(values).toString();history.replaceState(null,'','#'+route.page+(route.id?'/'+route.id:'')+(tail?'?'+tail:''));route=parseRoute(location.hash);}
function updateFoods(){const form=document.querySelector('#food-filters');const filters=Object.fromEntries(new FormData(form));const result=filterFoods(foods,filters);document.querySelector('#food-grid').innerHTML=result.length?views.foodCards(result):views.emptyState('没有匹配的食材','试试其他分类或基地，或重置筛选。','<button type="button" class="button secondary" data-reset-foods>重置筛选</button>');document.querySelector('#food-count').textContent=`${result.length} 个示意条目`;setQuery(filters);lastFoodList=location.hash;}
function updateEvents(){const values=Object.fromEntries(new FormData(document.querySelector('#event-filters')));setQuery(values);const risk={residue:'农药残留',metal:'重金属'}[values.risk]||'全部类型';document.querySelector('#event-count').textContent=`${risk}${values.year?' · '+values.year+' 年':''} · 0 条已整理事件`;}
function wirePage(){
  if(route.page==='foods'){const f=document.querySelector('#food-filters');f.addEventListener('change',updateFoods);f.addEventListener('input',e=>{if(e.target.name==='search')updateFoods();});f.addEventListener('submit',e=>{e.preventDefault();updateFoods();});f.addEventListener('reset',e=>{e.preventDefault();f.elements.category.value='all';f.elements.base.value='all';f.elements.search.value='';updateFoods();});document.querySelector('#food-grid').addEventListener('click',e=>{if(e.target.closest('[data-reset-foods]'))f.reset();});updateFoods();}
  if(route.page==='events'){const f=document.querySelector('#event-filters');f.addEventListener('change',updateEvents);f.addEventListener('input',updateEvents);f.addEventListener('submit',e=>{e.preventDefault();updateEvents();});f.addEventListener('reset',e=>{e.preventDefault();f.elements.risk.value='all';f.elements.year.value='';updateEvents();});updateEvents();}
  if(route.page==='inputs'||route.page==='base'){const bar=document.querySelector('[role=tablist]');if(!bar)return;bar.addEventListener('click',e=>{const tab=e.target.closest('[role=tab]');if(tab)chooseTab(tab);});bar.addEventListener('keydown',e=>{const tabs=[...bar.querySelectorAll('[role=tab]')];const index=tabs.indexOf(document.activeElement);if(index<0)return;let n=index;if(e.key==='ArrowRight')n=(index+1)%tabs.length;else if(e.key==='ArrowLeft')n=(index-1+tabs.length)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();chooseTab(tabs[n]);tabs[n].focus();});}
}
function chooseTab(tab){const bar=tab.closest('[role=tablist]');bar.querySelectorAll('[role=tab]').forEach(x=>{x.setAttribute('aria-selected',String(x===tab));x.tabIndex=x===tab?0:-1;});if(tab.dataset.inputTab){document.querySelector('#inputs-panel').innerHTML=views.inputCards(tab.dataset.inputTab);document.querySelector('#inputs-panel').setAttribute('aria-labelledby',tab.id);setQuery({type:tab.dataset.inputTab});}else{const x=bases.find(x=>x.id===route.id);document.querySelector('#base-panel').innerHTML=views.basePanel(x,tab.dataset.baseTab);document.querySelector('#base-panel').setAttribute('aria-labelledby',tab.id);setQuery({tab:tab.dataset.baseTab});}}
const titles={home:'看见生产与检测过程',foods:'菌养食材',food:'食材详情',inputs:'肥料与饲料',input:'产品资料',bases:'基地溯源',base:'基地资料',articles:'科普知识',article:'科普文章',events:'食材安全事件',event:'事件详情',about:'网站介绍','not-found':'页面暂不存在'};
function render({initial=false}={}){
  const next=parseRoute(location.hash);if(route.page==='foods')lastFoodList=location.hash.startsWith('#foods')?location.hash:lastFoodList;route=next;
  if(route.page==='home'&&renderedPage==='home'){if(route.section)jump('section-'+route.section);else window.scrollTo({top:0,behavior:'instant'});setActive(route.section||'home');return;}
  observer?.disconnect();document.documentElement.classList.remove('motion-ready');
  const page={home:()=>views.homeView(),foods:()=>views.foodsView(route),food:()=>views.foodView(route.id),inputs:()=>views.inputsView(route),input:()=>views.inputView(route.id),bases:()=>views.basesView(route),base:()=>views.baseView(route.id,route),articles:()=>views.articlesView(route),article:()=>views.articleView(route.id),events:()=>views.eventsView(route),event:()=>views.eventView(route.id),about:()=>views.aboutView()}[route.page]||views.missingView;
  main.innerHTML=page();renderedPage=route.page;document.title=(titles[route.page]||'菌养食材')+' · 菌养食材';wirePage();if(route.page==='food'){const back=main.querySelector('.back-link');if(back)back.href=lastFoodList;}window.scrollTo({top:0,behavior:'instant'});setActive(parentSection(route.page));reveal();if(!initial)main.focus({preventScroll:true});document.querySelector('#live-status').textContent=`已打开${titles[route.page]||'页面'}`;requestAnimationFrame(()=>{if(route.page==='home'&&route.section)jump('section-'+route.section);syncActive();});
}
window.addEventListener('hashchange',()=>render());setCollapsed(collapsed);syncMobile();render({initial:true});
